const row = (exportName, classification, surface, actor, identities, requirements, costs,
  consequences, blockers, nextActor, guidance, sourceKey, conditionalOverrides = [], clientReferenceAliases = []) => {
  const sourceAnchorIds = [...new Set(G[sourceKey])];
  const status = classification === 'external/manual-only' ? 'no-current-client-invocation-located' : 'served-ui-path';
  return {
    exportName, classification,
    ...(clientReferenceAliases.length ? { clientReferenceAliases } : {}),
    productPath: { status, surface, sourceAnchorIds },
    actor: { family: actor, identities, conditions: [requirements], conditionalOverrides, sourceAnchorIds },
    requirements: { summary: requirements, sourceAnchorIds },
    costs: { summary: costs, sourceAnchorIds },
    consequences: { summary: consequences, sourceAnchorIds },
    blockers: { summary: blockers, sourceAnchorIds },
    nextActor: { summary: nextActor, sourceAnchorIds },
    guidance: { status: classification === 'external/manual-only' ? 'not-present-in-current-call-path' : 'current-source-guidance', summary: guidance, sourceAnchorIds },
  };
};

